export function renderScopeForm(d,e){let review;try{review=JSON.parse(d.json);}catch{return '<p class="error-box">JSON 草稿格式有误，请在高级编辑中修正。</p>';}
 const field=(label,path,value,type='text')=>`<div class="field"><label for="scope-${path}">${label}</label>${type==='checkbox'?`<input id="scope-${path}" type="checkbox" data-scope-path="${path}" ${value?'checked':''}>`:type==='textarea'?`<textarea id="scope-${path}" data-scope-path="${path}">${e(value||'')}</textarea>`:`<input id="scope-${path}" data-scope-path="${path}" ${type==='number'?'type="number" min="1"':''} value="${e(Array.isArray(value)?value.join(', '):value??'')}">`}</div>`;
 return `<div class="scope-form"><h4>论文实验清单</h4>${(review.paper?.experiments||[]).map((x,i)=>`<fieldset class="scope-form-row"><legend>${e(x.id||'新实验')}</legend><div class="form-grid">${field('实验 ID',`paper.experiments.${i}.id`,x.id)}${field('图表编号（逗号分隔）',`paper.experiments.${i}.labels`,x.labels)}</div><div class="form-grid">${field('PDF 页码',`paper.experiments.${i}.page`,x.page,'number')}${field('对应结论 ID（逗号分隔）',`paper.experiments.${i}.conclusion_ids`,x.conclusion_ids)}</div>${field('论文原文',`paper.experiments.${i}.quote`,x.quote,'textarea')}<label class="check-label"><input type="checkbox" data-scope-path="paper.experiments.${i}.core" ${x.core?'checked':''}>支撑主要结论的核心实验</label><button class="btn text" data-scope-remove="paper.experiments:${i}">移除本项</button></fieldset>`).join('')}<button class="btn" data-scope-add="experiments">添加论文实验</button><h4>主要结论</h4>${(review.paper?.conclusions||[]).map((x,i)=>`<fieldset class="scope-form-row"><legend>${e(x.id||'新结论')}</legend><div class="form-grid">${field('结论 ID',`paper.conclusions.${i}.id`,x.id)}${field('PDF 页码',`paper.conclusions.${i}.page`,x.page,'number')}</div>${field('结论',`paper.conclusions.${i}.text`,x.text)}${field('论文原文',`paper.conclusions.${i}.quote`,x.quote,'textarea')}<button class="btn text" data-scope-remove="paper.conclusions:${i}">移除本项</button></fieldset>`).join('')}<button class="btn" data-scope-add="conclusions">添加主要结论</button><h4>原文与方法代码对应</h4>${(review.repository?.method_review?.citations||[]).map((x,i)=>`<fieldset class="scope-form-row"><legend>方法引用</legend>${field('PDF 页码',`repository.method_review.citations.${i}.page`,x.page,'number')}${field('原文',`repository.method_review.citations.${i}.quote`,x.quote,'textarea')}${field('代码相对路径（逗号分隔）',`repository.method_review.citations.${i}.paths`,x.paths)}<button class="btn text" data-scope-remove="repository.method_review.citations:${i}">移除引用</button></fieldset>`).join('')}<button class="btn" data-scope-add="citations">添加代码对应引用</button><h4>审核声明</h4>${field('清单审核说明','paper.inventory_review.notes',review.paper?.inventory_review?.notes,'textarea')}<label class="check-label"><input type="checkbox" data-scope-path="paper.inventory_review.complete" ${review.paper?.inventory_review?.complete?'checked':''}>已通读论文并核对全部实验清单</label>${field('方法核对来源','repository.method_review.source',review.repository?.method_review?.source)}${field('方法对应说明','repository.method_review.notes',review.repository?.method_review?.notes,'textarea')}<label class="check-label"><input type="checkbox" data-scope-path="repository.method_review.verified" ${review.repository?.method_review?.verified?'checked':''}>已按引用核对核心方法与代码</label></div>`;
}
export function editScopeDraft(d,path,value){const review=JSON.parse(d.json),keys=path.split('.');let obj=review;for(const key of keys.slice(0,-1))obj=obj[key]??={};const key=keys.at(-1);obj[key]=['labels','conclusion_ids','paths'].includes(key)?String(value).split(',').map(x=>x.trim()).filter(Boolean):value;d.json=JSON.stringify(review,null,2);}
